*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --bg:#0B0E14;--bg2:#0F131C;--card:#121722;--surface:#121722;
  --line:#1E2638;
  --gold:#F59E0B;--gold-dim:#D97706;--gold-soft:rgba(245,158,11,.12);
  --red:#F43F5E;--green:#10B981;
  --text:#F8FAFC;--muted:#94A3B8;--safe:env(safe-area-inset-bottom,0px);
  --radius:8px;--radius-sm:6px;
  --font:"Plus Jakarta Sans",system-ui,-apple-system,sans-serif;
  --font-mono:"Plus Jakarta Sans",system-ui,-apple-system,sans-serif;
  --btn-h:40px;--btn-h-m:44px;
}
html,body{height:100%;width:100%;min-height:100%;min-height:100dvh;background:var(--bg);color:var(--text);font-family:var(--font);
  overflow:hidden;overscroll-behavior:none;-webkit-overflow-scrolling:none;-webkit-tap-highlight-color:transparent;touch-action:manipulation;
  pointer-events:auto}
html{height:100%;height:100dvh}
body{position:relative;width:100%;height:100%;height:100dvh;min-height:100dvh;overflow:hidden;touch-action:manipulation;background:
  linear-gradient(165deg,#0B0E14 0%,#121722 48%,#0B0E14 100%)}
body,button,a,input,select,.asset-chip,.dur-chip,.odds-chip,.btn-trade,.btn-deposit,.qbtn,.mode-btn{touch-action:manipulation}
button:active:not(.drawer-item):not(.btn-close):not(.icon-btn),.qbtn:active,.dur-chip:active,.asset-chip:active,.btn-gold:active,.btn-deposit:active,.btn-trade:active{transform:scale(.98)}
.topbar-row .btn-deposit:active{transform:none}
body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:0;background:
  radial-gradient(900px 480px at 12% -8%,rgba(245,158,11,.04),transparent 52%),
  radial-gradient(720px 420px at 108% 8%,rgba(244,63,94,.03),transparent 48%),
  radial-gradient(640px 360px at 50% 110%,rgba(16,185,129,.03),transparent 50%)}
#particlesCanvas{position:fixed;inset:0;pointer-events:none;z-index:1;display:none}
@media (min-width:860px){#particlesCanvas{display:block}}
.screen{position:relative;z-index:2;height:100%;height:100dvh;max-height:100dvh;display:flex;flex-direction:column;min-height:0;overflow:hidden}
#screenAuth{overflow:hidden!important;-webkit-overflow-scrolling:none}
#screenTrade{overflow:hidden}
.hidden{display:none!important}
.glass{background:rgba(18,23,34,.88);border:1px solid var(--line);box-shadow:0 8px 28px rgba(0,0,0,.35);backdrop-filter:blur(16px)}

.lux-msg{display:flex;align-items:flex-start;gap:8px;padding:10px 14px;border-radius:12px;
  background:rgba(15,23,42,.95);border:1px solid rgba(16,185,129,.45);color:#F8FAFC;
  font-size:.78rem;font-weight:650;line-height:1.35;letter-spacing:.01em;
  box-shadow:0 8px 24px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.04);
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.lux-msg-ico{width:18px;height:18px;flex:0 0 18px;margin-top:1px;border-radius:50%;
  background:currentColor;opacity:.92;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='8' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5M12 16.2h.01' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'/></svg>") center/16px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='8' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5M12 16.2h.01' fill='none' stroke='black' stroke-width='2' stroke-linecap='round'/></svg>") center/16px no-repeat}
.lux-msg.ok,.toast.ok{border-color:rgba(16,185,129,.55);color:#A7F3D0;
  box-shadow:0 0 0 1px rgba(245,158,11,.28),0 8px 24px rgba(0,0,0,.32)}
.lux-msg.ok .lux-msg-ico,.toast.ok .lux-msg-ico{
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M8 12.2l2.6 2.6L16.2 9' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/16px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M8 12.2l2.6 2.6L16.2 9' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/16px no-repeat}
.lux-msg.err,.toast.err{border-color:rgba(244,63,94,.45);color:#FECDD3}
.lux-msg.err .lux-msg-ico,.toast.err .lux-msg-ico{
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5.2M12 16.4h.01' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/16px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5.2M12 16.4h.01' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/16px no-repeat}
.lux-msg.info{border-color:rgba(245,166,35,.35);color:#FDE68A}
.lux-msg-txt{min-width:0;flex:1 1 auto}
.toast{position:fixed;left:50%;top:75px;bottom:auto;transform:translate(-50%,-12px);
  z-index:230;opacity:0;pointer-events:none!important;max-width:min(320px,86vw);text-align:center;
  transition:opacity .28s ease,transform .28s ease}
.toast.show{opacity:1;transform:translate(-50%,0);animation:luxIn .34s ease;pointer-events:none!important}
.toast.micro,.toast.lux-msg.micro{
  top:calc(75px + env(safe-area-inset-top,0px));max-width:none;white-space:nowrap;
  font-size:11px!important;padding:4px 12px!important;border-radius:16px!important;
  background:rgba(18,22,34,.95)!important;border:1px solid rgba(245,158,11,.55)!important;
  color:#ffd166!important;backdrop-filter:blur(8px)!important;-webkit-backdrop-filter:blur(8px)!important;
  box-shadow:none!important;line-height:1.2;font-weight:700;letter-spacing:.02em;text-align:center}
.toast.micro .lux-msg-ico{display:none!important}
.toast.micro.show{animation:microToastIn .2s ease}
html body #toast.toast,
html body .toast.lux-msg{
  top:75px;max-width:min(320px,86vw);
  align-items:center;gap:6px;padding:5px 12px;border-radius:10px;
  font-size:12px;line-height:1.3;font-weight:650;
  background:linear-gradient(180deg,rgba(24,27,38,.96),rgba(14,16,24,.96));
  border:1px solid rgba(212,175,55,.38);
  color:#F3E6B5;
  box-shadow:0 8px 22px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.05)}
/* Notifications : fond sombre commun, seule la teinte change (doux, jamais criard). */
html body #toast.toast .lux-msg-ico{color:#D4AF37}
html body #toast.toast.ok,html body .toast.ok{border-color:rgba(52,211,153,.45);color:#C9F2DF}
html body #toast.toast.ok .lux-msg-ico{color:#34D399}
html body #toast.toast.err,html body .toast.err{border-color:rgba(251,113,133,.40);color:#FBD5DC}
html body #toast.toast.err .lux-msg-ico{color:#FB7185}
html body #toast.toast.info,html body .toast.info{border-color:rgba(212,175,55,.40);color:#F3E6B5}
html body #toast.toast.tie,html body .toast.tie{border-color:rgba(203,213,225,.32);color:#E2E8F0}
html body #toast.toast.tie .lux-msg-ico{color:#CBD5E1;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M6 9.5h12M6 14.5h12' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/14px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M6 9.5h12M6 14.5h12' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/14px no-repeat}
html body #toast.toast.toast-bal,
html body #toast.toast.toast-bal.err,
html body .toast.lux-msg.toast-bal{
  top:calc(16px + env(safe-area-inset-top,0px))!important;
  left:50%;transform:translate(-50%,0);
  width:max-content;max-width:min(280px,84vw);min-width:0;
  padding:7px 14px!important;border-radius:999px;
  font-size:.78rem!important;font-weight:650;letter-spacing:.02em;line-height:1.25;
  color:#F3E6B5!important;text-shadow:none;
  background:rgba(12,14,20,.92)!important;
  border:1px solid rgba(212,175,55,.42)!important;
  box-shadow:0 6px 18px rgba(0,0,0,.38);
  z-index:100050;white-space:nowrap;text-align:center}
html.fs-trade #toast.toast.toast-bal,
html.is-fullscreen #toast.toast.toast-bal{z-index:100050!important}
html body #toast.toast.toast-bal .lux-msg-txt{color:#F3E6B5!important;font-size:.78rem!important;font-weight:650}
html body #toast.toast.toast-bal .lux-msg-ico{display:none!important}
.toast .lux-msg-ico{width:14px;height:14px;flex:0 0 14px;margin-top:0}
@keyframes microToastIn{from{opacity:0;transform:translate(-50%,-8px)}to{opacity:1;transform:translate(-50%,0)}}
@keyframes luxIn{from{opacity:0;transform:translate(-50%,-16px)}to{opacity:1;transform:translate(-50%,0)}}
.btn-gold.busy{opacity:.72;pointer-events:none}
.chart-outcome{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%) scale(.92);z-index:15;
  display:none;align-items:center;justify-content:center;gap:4px;pointer-events:none;max-width:70%;
  font-weight:700;letter-spacing:.02em;opacity:0;white-space:nowrap}
.chart-outcome.show{display:inline-flex;opacity:1!important;transform:translate(calc(-50% + var(--ox,0px)),calc(-50% - var(--oy,0px))) scale(1);animation:outcomeFloat .9s ease forwards}
.chart-outcome.win{padding:5px 11px;border-radius:16px;color:#fff;font-size:13px;font-weight:700;
  background:linear-gradient(180deg,#16a34a,#22c55e);border:0;
  box-shadow:0 2px 10px rgba(34,197,94,.4);text-shadow:none;opacity:1!important}
.chart-outcome.win .outcome-wallet{width:16px;height:16px;flex-shrink:0;color:#F5C518}
.chart-outcome.lose{top:46%;bottom:auto;transform:translate(-50%,-50%) scale(.92);padding:2px 7px;border-radius:14px;
  font-size:11px;font-weight:700;color:#fff;background:#ef4444;border:0;
  box-shadow:0 2px 10px rgba(239,68,68,.4);text-shadow:none;animation:outcomePop .35s ease;z-index:12;opacity:1!important}
.chart-outcome.lose.show{transform:translate(calc(-50% + var(--ox,0px)),calc(-50% - var(--oy,0px))) scale(1);opacity:1!important}
@keyframes outcomePop{0%{opacity:0;transform:translate(-50%,-50%) scale(.7)}70%{transform:translate(-50%,-50%) scale(1.06)}100%{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes outcomeFloat{0%{opacity:1;transform:translate(calc(-50% + var(--ox,0px)),calc(-50% - var(--oy,0px)))}100%{opacity:0;transform:translate(calc(-50% + var(--ox,0px)),calc(-62% - var(--oy,0px)))}}
@keyframes outcomeFade{from{opacity:0}to{opacity:1}}
.timer-panel{margin:6px 0 4px;padding:8px 10px;border-radius:12px;border:1px solid var(--line);background:rgba(10,15,29,.65);text-align:center}
.timer-panel.active{display:block}
.timer-num{font-size:1.05rem;font-weight:900;color:#FFE082;font-variant-numeric:tabular-nums}
.timer-msg{font-size:.78rem;font-weight:800;margin-top:2px;min-height:1em}
.timer-panel.win .timer-msg{color:var(--green)}
.timer-panel.lose .timer-msg{color:#ff8a9b}
.timer-track{height:4px;border-radius:99px;background:rgba(255,255,255,.08);margin-top:6px;overflow:hidden}
.timer-fill{height:100%;width:0;background:linear-gradient(90deg,#FFD700,#FFA000)}
.bal-stack{display:flex;flex-direction:column;align-items:flex-start;gap:2px;flex:0 0 auto;min-width:max-content}
.bal-sub{font-size:.62rem;font-weight:700;color:var(--muted);letter-spacing:.02em}

.brand-lockup{display:flex;flex-direction:column;align-items:center;gap:8px}
.logo-mark{width:52px;height:52px;filter:none}
.brand,.brand-xl{font-family:var(--font);font-weight:800;letter-spacing:.02em;color:var(--gold)}
.brand-xl{font-size:1.85rem;text-align:center;text-shadow:none}
.brand-xl span,.brand span{color:#FBBF24}
.brand{font-size:.88rem}
.brand-domain{font-size:.62rem;font-weight:700;letter-spacing:.22em;color:var(--muted)}
.brand-sub{text-align:center;color:#f5a623;font-size:.78rem;margin:8px 0 16px;font-weight:600;letter-spacing:1px}
.auth-real-pitch{margin:0 0 12px;text-align:center;font-size:.72rem;font-weight:600;color:var(--muted);line-height:1.35}
.auth-real-pitch.hidden{display:none!important}
.tx-feed-row{display:grid;grid-template-columns:minmax(0,1fr) max-content;gap:8px;align-items:start;padding:10px 8px;border-bottom:1px solid rgba(255,255,255,.06)}
.tx-feed-row .tx-type{font-weight:900;font-size:.78rem}
.tx-feed-row .tx-meta{font-size:.62rem;color:var(--muted);margin-top:3px;line-height:1.35;overflow-wrap:anywhere}
.tx-feed-row .tx-amt{font-weight:900;font-size:.78rem;font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap;overflow:visible}
.tx-feed-row .tx-st{display:inline-block;margin-top:4px;font-size:.58rem;font-weight:800;padding:2px 6px;border-radius:999px}
#financeModal .modal-box{display:flex;flex-direction:column;overflow:hidden;max-height:78dvh;padding:16px 14px 10px}
#txFeed{flex:1 1 auto;min-height:0;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
.tx-st.ok{background:rgba(0,230,118,.15);color:var(--green)}
.tx-st.pending{background:rgba(255,215,0,.12);color:var(--gold)}
.tx-st.warn{background:rgba(148,163,184,.16);color:#CBD5E1}
.tx-st.bad{background:rgba(255,23,68,.15);color:#ff8aa0}
.legal{text-align:center;color:rgba(139,155,184,.72);font-size:.62rem;font-weight:700;margin-top:14px;letter-spacing:.04em}
.drawer-legal{margin-top:18px}

.auth-ambient{position:fixed;inset:0;pointer-events:none;background:
  url("../icons/pyramid-bg.svg?v=2096") center 72%/min(820px,170vw) auto no-repeat,
  radial-gradient(ellipse at 50% 0%,rgba(245,158,11,.05),transparent 46%)}
.auth-wrap{flex:1;display:flex;flex-direction:column;justify-content:flex-start;padding:30px 0 calc(8px + var(--safe));
  max-width:420px;margin-left:auto;margin-right:auto;width:92%}
.auth-card{border-radius:14px;padding:18px 16px 18px}
.auth-tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:rgba(11,14,20,.65);padding:4px;border-radius:var(--radius);margin-bottom:14px;border:1px solid var(--line)}
.auth-tab{border:0;background:transparent;color:var(--muted);font:inherit;font-weight:700;padding:10px;border-radius:var(--radius-sm);cursor:pointer;min-height:var(--btn-h)}
.auth-tab.on{background:var(--gold);color:#0B0E14}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}
.field label{font-size:.68rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
.field input,.field select,.phone-row select,.phone-row input{
  width:100%;background:rgba(11,14,20,.85);border:1px solid var(--line);border-radius:var(--radius);padding:12px 12px;
  color:var(--text);font:inherit;font-size:16px;outline:none;min-height:var(--btn-h-m)}
.field input:focus,.field select:focus,.phone-row input:focus,.phone-row select:focus{border-color:rgba(245,158,11,.55);box-shadow:0 0 0 3px rgba(245,158,11,.1)}
.phone-row{display:grid;grid-template-columns:108px 1fr;gap:8px}
.pass-wrap{position:relative;display:flex;align-items:center}
.pass-wrap input{width:100%;padding-right:52px}
.pass-toggle{position:absolute;right:4px;top:50%;transform:translateY(-50%);border:0;background:transparent;color:var(--muted);
  line-height:1;cursor:pointer;padding:8px;min-width:44px;min-height:44px;z-index:2;display:grid;place-items:center;border-radius:var(--radius-sm);touch-action:manipulation;-webkit-tap-highlight-color:transparent}
.pass-toggle svg{width:20px;height:20px;display:block;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.pass-toggle:hover{color:var(--text);background:rgba(255,255,255,.04)}
.err-msg{min-height:0;font-size:.7rem;color:#FECDD3;font-weight:600;display:none}
.err-msg.on{display:flex;align-items:flex-start;gap:8px;margin-top:6px;padding:8px 10px;border-radius:10px;
  background:rgba(11,14,20,.62);border:1px solid rgba(244,63,94,.4);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  animation:luxInLocal .28s ease}
.err-msg.on::before{content:"";width:14px;height:14px;flex:0 0 14px;margin-top:1px;background:currentColor;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5.2M12 16.4h.01' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/14px no-repeat;
  mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='9' fill='none' stroke='black' stroke-width='2'/><path d='M12 8v5.2M12 16.4h.01' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round'/></svg>") center/14px no-repeat}
/* OTP cooldown : carré collé au texte, une seule ligne */
#err-otpCode.otp-wait-live.on{
  display:inline-block!important;
  width:auto!important;
  max-width:100%;
  height:auto!important;
  min-height:0!important;
  margin:6px auto 0;
  padding:4px 8px;
  color:#FDE68A;
  border:1px solid rgba(245,158,11,.55);
  background:rgba(245,158,11,.12);
  border-radius:8px;
  white-space:nowrap;
  line-height:1.15;
  font-size:.74rem;
  font-weight:700}
#otpModal .field:has(#err-otpCode.otp-wait-live.on){display:flex;flex-direction:column;align-items:center}
#err-otpCode.otp-wait-live.on::before{
  content:none!important;display:none!important;width:0!important;height:0!important}
@keyframes luxInLocal{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}
.check-row{display:flex;gap:10px;align-items:flex-start;font-size:.75rem;color:var(--muted);line-height:1.35;margin:4px 0 8px;cursor:pointer}
.check-row input{margin-top:2px;accent-color:var(--gold);width:16px;height:16px;flex-shrink:0}
.link-forgot{display:block;width:100%;background:none;border:0;color:var(--gold);font:inherit;font-size:.7rem;font-weight:700;
  text-align:right;margin:0 0 10px;cursor:pointer;white-space:nowrap}
.btn-gold{width:100%;border:0;border-radius:var(--radius);padding:0 14px;min-height:var(--btn-h);font:inherit;font-weight:800;letter-spacing:.04em;
  text-transform:uppercase;cursor:pointer;background:var(--gold);color:#0B0E14;
  box-shadow:none}
@media (max-width:859px){.btn-gold{min-height:var(--btn-h-m)}}
.btn-gold:active{transform:scale(.98)}
.btn-gold:disabled,.btn-gold[disabled]{opacity:.45;cursor:not-allowed;transform:none}

.trade-shell{flex:1;display:flex;flex-direction:column;min-height:0;width:100%;max-width:28rem;margin:0 auto;overflow:visible}
.topbar{flex-shrink:0;padding:0;padding-top:env(safe-area-inset-top,0px);background:rgba(10,15,29,.86);border-bottom:1px solid var(--line);backdrop-filter:blur(16px);position:relative;z-index:50}
.topbar-row{display:flex;align-items:center;width:100%;padding:6px 8px;gap:6px;position:relative;min-height:40px}
.topbar-row .btn-deposit{position:static;left:auto;margin-left:0;margin-right:0;min-width:max-content;z-index:6;flex:0 0 auto;overflow:visible}
.auth-quick{display:flex;gap:5px;align-items:center;flex-shrink:0;min-width:0;z-index:2}
.topbar-actions{display:flex;align-items:center;gap:4px;flex-shrink:0;margin-left:auto}
.brand-lockup.mini{flex-direction:row;gap:4px;flex-shrink:0;min-width:0;cursor:pointer}
.brand-lockup.mini .brand{font-size:.7rem;white-space:nowrap}
.logo-mark.sm{width:22px;height:22px}
.topbar-mode{display:flex;align-items:stretch;padding:0 8px 6px;min-width:0}
.mode-switch{flex:1;width:100%;min-width:0;display:grid;grid-template-columns:minmax(0,.78fr) minmax(0,1.32fr);gap:3px;background:rgba(10,15,29,.85);
  border:1px solid var(--line);border-radius:12px;padding:3px;overflow:hidden}
.mode-btn{border:1px solid transparent;background:rgba(255,255,255,.03);color:var(--muted);font:inherit;font-size:.58rem;font-weight:800;
  padding:8px 4px;border-radius:9px;cursor:pointer;white-space:nowrap;line-height:1.15;min-width:0;width:100%;opacity:.72;transform:scale(.96);
