.balance-row{display:flex;align-items:center;gap:10px;padding:2px 8px 4px}
.balance-card{flex:1;display:flex;align-items:center;justify-content:center;border-radius:12px;padding:6px 12px!important;cursor:pointer;min-width:0}
#fsTopBalance{cursor:pointer}
.balance-card .bal{font-weight:700;color:#FBBF24;font-size:1.2rem;letter-spacing:.01em;white-space:nowrap;
