.asset-chip[data-asset="nexusprime"]{border-color:rgba(34,211,238,.42)}
.asset-chip[data-asset="nexusprime"] .asset-ico,.asset-chip[data-asset="nexusprime"].on{color:#22D3EE}
.asset-chip[data-asset="nexusprime"].on{border-color:#22D3EE;box-shadow:0 0 10px rgba(34,211,238,.25);background:rgba(34,211,238,.08)}
.asset-chip[data-asset="v75"]{border-color:rgba(233,30,99,.42)}
.asset-chip[data-asset="v75"] .asset-ico,.asset-chip[data-asset="v75"].on{color:#E91E63}
.asset-chip[data-asset="v75"].on{border-color:#E91E63;box-shadow:0 0 10px rgba(233,30,99,.28);background:rgba(233,30,99,.08)}
.asset-chip[data-asset="titanpulse"]{border-color:rgba(255,255,255,.28)}
.asset-chip[data-asset="titanpulse"] .asset-ico,.asset-chip[data-asset="titanpulse"].on{color:#FFFFFF}
.asset-chip[data-asset="titanpulse"].on{border-color:rgba(255,255,255,.45);box-shadow:0 0 8px rgba(255,255,255,.18);background:rgba(255,255,255,.06)}
.asset-chip{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.04);border-radius:8px;text-align:left;
  color:var(--text);font:inherit;cursor:pointer;overflow:hidden;box-sizing:border-box}
.asset-chip:not(.on){border:1px solid rgba(255,255,255,.08)!important;box-shadow:none!important;background:rgba(255,255,255,.04)!important}
.asset-chip .k{display:none!important}
.asset-chip .n{font-size:10px;font-weight:700;margin-top:0;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.asset-chip.on{border-color:rgba(245,158,11,.55);box-shadow:none;background:rgba(245,158,11,.08)}
.asset-chip[data-asset="v100"].on{border-width:1.5px;border-color:#10B981;box-shadow:0 0 12px rgba(16,185,129,.35);background:linear-gradient(180deg,rgba(16,185,129,.28),rgba(6,78,59,.18));color:#10B981}
.asset-chip[data-asset="stable"].on{border-width:1.5px;border-color:#E53935;box-shadow:0 0 12px rgba(229,57,53,.4);background:linear-gradient(180deg,rgba(229,57,53,.28),rgba(127,29,29,.18));color:#E53935}
.asset-chip[data-asset="apex500"].on{border-width:1.5px;border-color:#A855F7;box-shadow:0 0 12px rgba(168,85,247,.4);background:linear-gradient(180deg,rgba(168,85,247,.3),rgba(76,29,149,.2));color:#C084FC}
.asset-chip[data-asset="horizon50"].on{border-width:1.5px;border-color:#ff9800;box-shadow:0 0 12px rgba(255,152,0,.35);background:linear-gradient(180deg,rgba(255,152,0,.28),rgba(124,63,0,.18));color:#ff9800}
.asset-chip[data-asset="crash300"].on{
  border-width:1.5px!important;border-style:solid!important;border-color:transparent!important;
  background:linear-gradient(180deg,rgba(18,10,22,.94),rgba(8,10,18,.96)) padding-box,
    linear-gradient(90deg,#ff007f,#7928ca,#00d2ff) border-box!important;
  box-shadow:0 0 14px rgba(229,46,113,.4)!important;color:inherit}
