.asset-chip[data-asset="titanpulse"].on{border-width:1.5px;border-color:#FFFFFF;box-shadow:0 0 14px rgba(255,255,255,.45);background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,.04));color:#FFFFFF}
