/* OTP inscription */
.otp-box{max-width:400px;width:calc(100% - 28px)}
.otp-lead{margin:0 0 16px;color:var(--muted);font-size:.88rem;line-height:1.45;text-align:center}
.otp-lead strong{color:#E8EEF9;font-weight:700;word-break:break-all}
.otp-input{text-align:center;font-size:1.55rem;font-weight:800;letter-spacing:.42em;padding:14px 10px 14px 18px!important}
.otp-resend-row{display:flex;align-items:center;justify-content:center;gap:0;margin-top:14px}
.otp-resend-row .mini:disabled{opacity:.45;cursor:not-allowed}
.otp-timer,.otp-resend-wait{display:none!important}
/* Le décompte vit sur ce lien discret, et nulle part ailleurs : une alerte
   « Wait 59 s » s'ouvrait auparavant entre les champs du formulaire. */
.otp-resend-line{display:flex;align-items:center;gap:8px;margin:8px 0 0;flex-wrap:wrap}
.otp-resend-link{background:none;border:0;padding:0;font:inherit;font-size:.72rem;font-weight:700;
  color:#F5A623;cursor:pointer;text-decoration:underline;text-underline-offset:2px}
.otp-resend-link:disabled{color:var(--muted);text-decoration:none;cursor:default;opacity:.7}
.otp-resend-wait{font-size:.68rem;font-weight:600;color:var(--muted)}

/* ===== Full Screen Trading Overlay (IQ Option style, 0° — no rotate) ===== */
.fs-trade-overlay{
  display:none;position:fixed;inset:0;width:100%;height:100vh;height:100dvh;
  z-index:99999;background:#0B0E14;overflow:hidden;margin:0;padding:0;
  box-sizing:border-box;flex-direction:column}
.fs-trade-overlay.on{display:flex!important;flex-direction:column!important;overflow:hidden!important;
  height:100vh!important;height:100dvh!important;width:100%!important}
.fs-trade-topbar{
  flex:0 0 auto;display:flex;align-items:center;justify-content:space-between;gap:12px;
  width:100%;min-height:40px;padding:6px 12px;padding-top:max(8px,env(safe-area-inset-top,0px));
  border-bottom:1px solid var(--line);background:rgba(11,14,20,.98);z-index:6}
.fs-top-end{display:flex;align-items:center;flex-shrink:0;gap:8px;margin-left:auto}
.fs-top-mid{display:none;flex-direction:column;align-items:center;justify-content:center;min-width:0;flex:1}
.fs-mode-label{display:none}
.fs-mode-switch{display:grid;grid-template-columns:minmax(44px,.82fr) 26px minmax(58px,1.18fr);align-items:center;justify-items:stretch;gap:4px;margin-top:5px;padding:3px 4px;max-width:min(220px,100%);border-radius:999px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08)}
.fs-mode-btn{border:0;background:transparent;color:#94A3B8;font:inherit;font-size:10px;font-weight:700;letter-spacing:.06em;
  padding:4px 8px;border-radius:999px;cursor:pointer;min-height:24px;min-width:0;transform:none;opacity:1}
.fs-mode-btn[data-mode="demo"]{padding:4px 8px;min-height:24px;font-size:9px;font-weight:700;letter-spacing:.08em;justify-self:stretch}
.fs-mode-btn[data-mode="real"]{padding:6px 14px;min-height:28px;font-weight:800;font-size:10px;letter-spacing:.06em;justify-self:stretch}
.fs-mid-plus{width:26px;height:26px;min-width:26px;border-radius:50%;border:1px solid rgba(245,197,24,.75);
  background:linear-gradient(180deg,#FDE68A,#D97706);color:#000;
  padding:0;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;
  box-shadow:0 0 10px rgba(245,158,11,.35);flex-shrink:0;justify-self:center}
.fs-mode-btn.on{background:rgba(245,197,24,.16);color:#FDE68A;box-shadow:0 0 10px rgba(245,197,24,.2)}
html.fs-trade .fs-mode-btn.mode-btn,
html.is-fullscreen .fs-mode-btn.mode-btn{transform:none!important;font-size:10px;font-weight:700;box-shadow:none}
html.fs-trade .fs-mode-btn.mode-btn[data-mode="demo"],
html.is-fullscreen .fs-mode-btn.mode-btn[data-mode="demo"]{padding:4px 8px;min-height:24px;font-size:9px}
html.fs-trade .fs-mode-btn.mode-btn[data-mode="real"],
html.is-fullscreen .fs-mode-btn.mode-btn[data-mode="real"]{padding:6px 14px;min-height:28px;font-size:10px;font-weight:800}
html.fs-trade .fs-mode-btn.mode-btn.on[data-mode="demo"],
html.is-fullscreen .fs-mode-btn.mode-btn.on[data-mode="demo"]{
  background:rgba(245,197,24,.18);color:#FDE68A;border-color:transparent;box-shadow:none}
html.fs-trade .fs-mode-btn.mode-btn:not(.on)[data-mode="demo"],
html.is-fullscreen .fs-mode-btn.mode-btn:not(.on)[data-mode="demo"]{
