html body .btn-close:not(#btnCloseDrawer):not(#oroX1):not(#oroX2):focus-visible{border-color:rgba(245,197,24,.9)!important;color:#F5C518!important;background:rgba(18,24,36,.92)!important}
html body .btn-close:not(#btnCloseDrawer):not(#oroX1):not(#oroX2):active{transform:scale(.94)!important}
html body .btn-close:not(#btnCloseDrawer) .x-ico{width:14px;height:14px;display:block;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round}
