@media (max-width:859px) and (orientation:portrait){
  html:not(.fs-trade):not(.is-fullscreen) body #screenTrade#screenTrade#screenTrade #tradeWrap#tradeWrap#tradeWrap:not(#z1):not(#z2):not(#z3) #oddsRow{
    display:flex!important;justify-content:space-around!important;align-items:flex-end!important;height:58px!important;min-height:58px!important;padding:0 2px 4px!important;overflow:visible!important;position:relative!important}
