/* ---- Sky Rush / Jet Man / Rocket : rayons, ligne des derniers tours ---- */
html body #casinoModal .crash-stage{background:none!important;padding-top:36px!important}
#casinoModal .crash-rays{position:absolute;left:-70%;bottom:-75%;width:240%;aspect-ratio:1;border-radius:50%;pointer-events:none;background:repeating-conic-gradient(from 0deg,rgba(255,255,255,.07) 0 5deg,transparent 5deg 15deg);-webkit-mask:radial-gradient(circle,#000 20%,transparent 62%);mask:radial-gradient(circle,#000 20%,transparent 62%)}
#casinoModal .crash-stage.flying .crash-rays{animation:csRays 24s linear infinite}
@keyframes csRays{to{transform:rotate(360deg)}}
html.oro-lite #casinoModal .crash-rays{animation:none!important}
#casinoModal .crash-hist{position:absolute;left:10px;right:10px;top:6px;z-index:3;display:flex;gap:5px;overflow:hidden;white-space:nowrap}
#casinoModal .crash-hist i{font:800 11px system-ui;font-style:normal;padding:3px 8px;border-radius:10px;background:rgba(0,0,0,.35)}
#casinoModal .crash-hist i.lo{color:#60a5fa}
#casinoModal .crash-hist i.mid{color:#c084fc}
#casinoModal .crash-hist i.hi{color:#f472b6}
html body #casinoModal .plane{filter:drop-shadow(0 6px 10px rgba(0,0,0,.5))}
html body #casinoModal .plane svg{width:100%;height:100%}
html body #casinoModal .crash-n{font-size:clamp(46px,14vw,68px)}
/* ---- Penalty (vu de derrière le ballon) ---- */
html body #casinoModal .pen3{padding:0!important;margin:0 -14px;position:relative;min-height:240px}
#casinoModal .pen3 .pen-scene{position:absolute;inset:0;width:100%;height:100%}
#casinoModal .pen3.net-hit .pen-scene{animation:penNet .45s ease-out}
@keyframes penNet{30%{transform:translateY(-3px)}60%{transform:translateY(2px)}}
#casinoModal .pen-dots{position:absolute;top:8px;left:50%;transform:translateX(-50%);display:flex;gap:6px;z-index:3;padding:4px 8px;border-radius:12px;background:rgba(0,0,0,.35)}
#casinoModal .pen-dots i{width:14px;height:14px;border-radius:50%;background:rgba(255,255,255,.25)}
#casinoModal .pen-dots i.g{background:#22c55e;box-shadow:0 0 6px #22c55e}
#casinoModal .pen-dots i.m{background:#ef4444}
#casinoModal .pen-t{position:absolute;top:33%;width:38px;height:38px;margin-left:-19px;z-index:3;border-radius:50%;border:3px solid rgba(255,255,255,.85);background:rgba(255,255,255,.12);padding:0;transition:transform .15s}
#casinoModal .pen-t::after{content:"";position:absolute;inset:9px;border-radius:50%;background:rgba(255,255,255,.7)}
#casinoModal .pen-t.on{border-color:#FACC15;background:rgba(250,204,21,.3);transform:scale(1.15)}
#casinoModal .pen-t.on::after{background:#FACC15}
#casinoModal .kp3{position:absolute;left:42%;width:16%;bottom:49.5%;aspect-ratio:70/90;z-index:2;transform-origin:50% 100%;transition:transform .55s cubic-bezier(.3,.8,.4,1)}
#casinoModal .kp3 svg,#casinoModal .ball3 svg{width:100%;height:100%;display:block}
#casinoModal .ball3{position:absolute;left:44%;width:12%;bottom:7%;aspect-ratio:1;z-index:4;transition:transform .6s cubic-bezier(.2,.7,.3,1);filter:drop-shadow(0 8px 8px rgba(0,0,0,.45))}
html body #casinoModal .pen-msg,html body #casinoModal .pen2{display:none!important}
/* ---- Mines (bleu, cases en relief) ---- */
#casinoModal .mn-stage{justify-content:center}
#casinoModal .mn-info{display:flex;justify-content:space-between;width:100%;max-width:min(340px,44vh);font:800 13px system-ui;color:#dbeafe}
