html body #casinoModal .mn{gap:8px;max-width:min(340px,44vh)}
html body #casinoModal .mn button{border-radius:12px;background:linear-gradient(160deg,#3b82f6,#1e40af);box-shadow:inset 0 2px 0 rgba(255,255,255,.3),0 4px 0 #172554;display:grid;place-items:center;padding:0}
html body #casinoModal .mn button svg{width:72%;height:72%}
