html body #casinoModal .tw-stage{background:none!important;padding:6px 14px 0!important;justify-content:flex-end}
#casinoModal .tw-city{position:absolute;left:0;right:0;bottom:0;height:38%;pointer-events:none;opacity:.55;
  background:linear-gradient(#1e3a8a,#1e3a8a) 4% 100%/12% 70% no-repeat,linear-gradient(#1e40af,#1e40af) 18% 100%/9% 45% no-repeat,linear-gradient(#1e3a8a,#1e3a8a) 80% 100%/13% 80% no-repeat,linear-gradient(#1e40af,#1e40af) 95% 100%/8% 55% no-repeat}
html body #casinoModal .tw{position:relative;z-index:1;gap:4px;padding:8px 8px 0;max-width:300px;border-radius:6px 6px 0 0;background:linear-gradient(90deg,#a8a29e,#e7e5e4 50%,#a8a29e);box-shadow:0 10px 30px rgba(0,0,0,.35)}
