#casinoModal .slot2{position:relative;width:min(320px,86vw);padding:10px 12px 14px;border-radius:24px;background:linear-gradient(180deg,#ef4444,#991b1b);box-shadow:inset 0 0 0 4px #FACC15,inset 0 0 0 7px #b45309,0 16px 34px rgba(0,0,0,.45)}
#casinoModal .slot2-top{text-align:center;font:900 20px "Plus Jakarta Sans",system-ui,sans-serif;color:#FDE047;letter-spacing:2px;text-shadow:0 2px 0 #92400e;margin-bottom:8px}
