#casinoModal .slot2-win span{aspect-ratio:.9;border-radius:14px;display:grid;place-items:center;background:linear-gradient(180deg,#fff,#f1f5f9 50%,#cbd5e1);box-shadow:inset 0 6px 10px rgba(0,0,0,.18),inset 0 -6px 10px rgba(0,0,0,.12)}
