#casinoModal .pay2.kn{grid-template-columns:repeat(3,1fr)}
#casinoModal .pay2.kn small::after{content:" ✓"}
html body #casinoModal .slot-stage .pay,html body #casinoModal .scr-stage .pay{display:none}
