#casinoModal .sb-dome::before{content:"";position:absolute;left:50%;top:-12px;width:22px;height:22px;margin-left:-11px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#FFF6C8,#F5B700 60%,#9A6A00)}
